package com.musitu.store;
import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.os.Build;import org.json.*;
public class UpdateCheckReceiver extends BroadcastReceiver{
  @Override public void onReceive(Context c,Intent intent){final PendingResult p=goAsync();new Thread(()->{try{JSONObject cat=StoreCore.fetchVerified(c),r=StoreCore.chemistry(cat);long cur=r.optLong("versionCode",-1),have=StoreCore.installedVersion(c);if(have>=0&&cur>have)notify(c,r.optString("version","new"));}catch(Exception ignored){}finally{p.finish();}}).start();}
  static void notify(Context c,String v){NotificationManager n=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);String ch="musitu_store_updates";if(Build.VERSION.SDK_INT>=26)n.createNotificationChannel(new NotificationChannel(ch,"MUSITU Store updates",NotificationManager.IMPORTANCE_DEFAULT));if(Build.VERSION.SDK_INT>=33&&c.checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)return;Intent i=new Intent(c,MainActivity.class);PendingIntent pi=PendingIntent.getActivity(c,0,i,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,ch):new Notification.Builder(c);b.setSmallIcon(android.R.drawable.stat_sys_download_done).setContentTitle("MUSITU Chemistry update available").setContentText("Version "+v+" is verified and ready.").setContentIntent(pi).setAutoCancel(true);n.notify(1201,b.build());}
}
